# Initially generated by GitHub Copilot.
"""Claim annotation wrapper for the authored MAM-parsed docs.

A *claim* is a falsifiable statement made by the docs about the data corpus
(MAM-parsed-plain or MAM-parsed-plus). Each claim is given a stable id and
registered in `REGISTRY` at import time. A separate verifier module is
expected to map each id to a function that programmatically checks the
claim against the corpus.

Usage (inline, returns its payload unchanged so it slots into the existing
author-helper calls):

    author.para(claim(
        "mp.plus.verse.is-3-tuple",
        "Each verse is a 3-element array [C, D, E].",
        kind="struct", subject="mp:plus",
        data={"shape": ["sep", "label", "text"]},
    ))

For module-level constants (e.g. row tables, JSON snippets) wrap the value
at its definition site:

    KQ_ROWS = claim(
        "mp.both.templates.kq.set",
        [ ... ],
        kind="enum", subject="mp:both",
        data={"templates": ["כו״ק", ...]},
    )

Fields:
    id        — unique, stable, dot-segmented kebab. Top-level segment is
                always ``mp`` (MAM-parsed); second segment is one of
                ``plain``, ``plus``, ``both``.
    kind      — one of KINDS below.
    subject   — one of SUBJECTS below; matches the second id segment.
    data      — optional structured payload for the verifier (parsed JSON,
                list of expected template names, etc.). May be None during
                bootstrap; verifier authors will fill it in.

The wrapper performs *no* verification itself; it only records the claim.
"""

from dataclasses import dataclass
import inspect
from typing import Any

KINDS = frozenset(
    {
        "struct",  # shape/structure of objects or arrays
        "enum",  # a closed set of values (template names, keys, etc.)
        "format",  # how something is encoded (e.g. id/key format)
        "example",  # a concrete instance asserted to occur in the corpus
        "convention",  # naming/ordering convention
    }
)

SUBJECTS = frozenset({"mp:plain", "mp:plus", "mp:both"})


@dataclass(frozen=True)
class ClaimRecord:
    id: str
    kind: str
    subject: str
    data: Any
    defined_in: str  # module name where the claim() call lives


REGISTRY: dict[str, ClaimRecord] = {}


def claim(claim_id: str, payload, *, kind: str, subject: str, data: Any = None):
    """Register a claim and return `payload` unchanged.

    Raises on duplicate id, unknown kind, or unknown subject.
    """
    if kind not in KINDS:
        raise ValueError(f"claim {claim_id!r}: unknown kind {kind!r}")
    if subject not in SUBJECTS:
        raise ValueError(f"claim {claim_id!r}: unknown subject {subject!r}")
    expected_ns = subject.split(":", 1)[1]  # "plain" | "plus" | "both"
    if not claim_id.startswith(f"mp.{expected_ns}."):
        raise ValueError(
            f"claim {claim_id!r}: id must start with 'mp.{expected_ns}.' for subject {subject!r}"
        )
    if claim_id in REGISTRY:
        raise ValueError(f"duplicate claim id: {claim_id!r}")
    frame = inspect.stack()[1]
    module = inspect.getmodule(frame.frame)
    defined_in = module.__name__ if module is not None else "<unknown>"
    REGISTRY[claim_id] = ClaimRecord(
        id=claim_id,
        kind=kind,
        subject=subject,
        data=data,
        defined_in=defined_in,
    )
    return payload
